#requires -Version 5.1
[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$Stage3V6RunRoot,
    [Parameter(Mandatory=$true)][string]$OutputRoot,
    [ValidateRange(1,10)][int]$PerStratum = 2,
    [ValidateRange(20,500)][int]$MaxReviewRows = 180,
    [switch]$SelfTest
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
function Write-Utf8NoBom{param([string]$Path,[string]$Content);$p=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $p -PathType Container)){New-Item -ItemType Directory -Path $p -Force|Out-Null};[IO.File]::WriteAllText($Path,$Content,(New-Object Text.UTF8Encoding($false)))}
function Get-Sha{param([string]$Path);return(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Stable-Sha{param([string]$Text);$s=[Security.Cryptography.SHA256]::Create();try{return([BitConverter]::ToString($s.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Bool{param([object]$Value,[string]$Label);$x=([string]$Value).Trim().ToLowerInvariant();if($x-eq'true'){return$true};if($x-eq'false'){return$false};throw "Malformed boolean ${Label}: $Value"}
function Assert-Logic{
 param([object[]]$Rows);$errors=New-Object System.Collections.ArrayList;$i=0
 foreach($r in $Rows){$i++;try{$v6=([string]$r.v6_match_status).Trim();$v5=([string]$r.v5_match_status).Trim();$reason=([string]$r.v6_filter_reason).Trim();$short=Bool $r.v5_short_default_symbol "row $i short";$approved=Bool $r.v5_approved_nondefault_same_record "row $i approved";$structured=Bool $r.v5_structured_symbol_exact "row $i structured";$parenthetical=Bool $r.v5_parenthetical_market_ticker "row $i parenthetical";$local=Bool $r.v6_local_market_context "row $i local"
   if($v6-notin@('MATCH','REJECT_CONTEXT','REJECT_V5_SHORT_SYMBOL_CONTEXT','REJECT_V6_SHORT_SYMBOL_LOCAL_MARKET_CONTEXT')){throw "unexpected V6 status $v6"}
   if($v6-eq'REJECT_V6_SHORT_SYMBOL_LOCAL_MARKET_CONTEXT'){if($v5-ne'MATCH'-or-not$short-or$approved-or$structured-or$parenthetical-or$local-or$reason-ne'SHORT_DEFAULT_REQUIRES_LOCAL_MARKET_OR_HIGH_SPECIFICITY'){throw'new V6 reject lineage inconsistent'}}
   elseif($v6-eq'REJECT_V5_SHORT_SYMBOL_CONTEXT'){if($v5-ne'REJECT_V5_SHORT_SYMBOL_CONTEXT'-or$reason-ne'V5_SHORT_SYMBOL_REJECT_PRESERVED'){throw'V5 short reject not preserved'}}
   elseif($v6-eq'REJECT_CONTEXT'){if($v5-ne'REJECT_CONTEXT'-or$reason-ne'V2_CONTEXT_REJECT'){throw'context reject not preserved'}}
   else{if($v5-ne'MATCH'){throw'V6 match does not originate from V5 match'};if(-not$short-and$reason-ne'NOT_SHORT_DEFAULT'){throw'non-short reason mismatch'};if($short-and-not($approved-or$structured-or$parenthetical-or$local)){throw'short V6 match lacks high-specificity evidence'}}
  }catch{[void]$errors.Add("row ${i}: $($_.Exception.Message)")}}
 return[pscustomobject]@{status=if($errors.Count-eq0){'PASS'}else{'FAIL'};errors=@($errors.ToArray())}
}
function Select-Rows{param([object[]]$Rows,[int]$Take,[int]$Maximum);$p=New-Object System.Collections.ArrayList;foreach($r in $Rows){$surface=([string]$r.matched_surfaces).Trim();if([string]::IsNullOrWhiteSpace($surface)){$surface='NONE'};$stratum=([string]$r.v6_match_status)+'|'+([string]$r.v6_filter_reason)+'|'+$surface;$key=([string]$r.base_asset_id)+'|'+([string]$r.alias_text).ToLowerInvariant()+'|'+([string]$r.record_id)+'|'+([string]$r.v6_match_status);[void]$p.Add([pscustomobject]@{row=$r;stratum=$stratum;hash=(Stable-Sha $key)})};$s=New-Object System.Collections.ArrayList;foreach($g in @($p|Group-Object stratum|Sort-Object Name)){foreach($x in @($g.Group|Sort-Object hash|Select-Object -First $Take)){[void]$s.Add($x)}}
 $mandatory=@(
  @{label='IP Exchange reject';test={param($x)$x.row.base_asset_id-eq'IP'-and$x.row.page_title-match'IP Exchange'-and$x.row.v6_match_status-eq'REJECT_V6_SHORT_SYMBOL_LOCAL_MARKET_CONTEXT'}},
  @{label='OM rally retain';test={param($x)$x.row.base_asset_id-eq'OM'-and$x.row.page_title-match'OM rally'-and$x.row.v6_match_status-eq'MATCH'}},
  @{label='OP_RETURN reject';test={param($x)$x.row.base_asset_id-eq'OP'-and$x.row.page_title-match'OP_RETURN'-and$x.row.v6_match_status-eq'REJECT_V5_SHORT_SYMBOL_CONTEXT'}},
  @{label='IP infrastructure reject';test={param($x)$x.row.base_asset_id-eq'IP'-and$x.row.page_title-match'IP Infrastructure'-and$x.row.v6_match_status-eq'REJECT_V5_SHORT_SYMBOL_CONTEXT'}},
  @{label='Arweave ticker retain';test={param($x)$x.row.base_asset_id-eq'AR'-and$x.row.page_title-match'Arweave \(AR\)'-and$x.row.v6_match_status-eq'MATCH'}},
  @{label='Story ticker retain';test={param($x)$x.row.base_asset_id-eq'IP'-and$x.row.page_title-match'Story \(IP\)'-and$x.row.v6_match_status-eq'MATCH'}})
 foreach($m in $mandatory){$c=@($p|Where-Object{& $m.test $_}|Sort-Object hash|Select-Object -First 1);if($c.Count-eq0){throw "Mandatory V6 review case missing: $($m.label)"};if(@($s|Where-Object hash-eq$c[0].hash).Count-eq0){[void]$s.Add($c[0])}}
 if($s.Count-gt$Maximum){$s=New-Object System.Collections.ArrayList;foreach($x in @($p|Sort-Object hash|Select-Object -First $Maximum)){[void]$s.Add($x)}};return@($s.ToArray())}
function SelfTest{$rows=@();$baseRows=@(
 [pscustomobject]@{v6_match_status='REJECT_V6_SHORT_SYMBOL_LOCAL_MARKET_CONTEXT';v6_filter_reason='SHORT_DEFAULT_REQUIRES_LOCAL_MARKET_OR_HIGH_SPECIFICITY';v6_local_market_context='False';v5_match_status='MATCH';v5_short_default_symbol='True';v5_approved_nondefault_same_record='False';v5_structured_symbol_exact='False';v5_parenthetical_market_ticker='False';base_asset_id='IP';alias_text='IP';record_id='1';page_title='IP Exchange';matched_surfaces='PAGE_TITLE'},
 [pscustomobject]@{v6_match_status='MATCH';v6_filter_reason='TITLE_LOCAL_MARKET_SHORT_SYMBOL';v6_local_market_context='True';v5_match_status='MATCH';v5_short_default_symbol='True';v5_approved_nondefault_same_record='False';v5_structured_symbol_exact='False';v5_parenthetical_market_ticker='False';base_asset_id='OM';alias_text='OM';record_id='2';page_title='OM rally';matched_surfaces='PAGE_TITLE'});foreach($r in $baseRows){$rows+=$r};if((Assert-Logic $rows).status-ne'PASS'){throw'V6 logic selftest'};Write-Host 'SELF-TEST: PASS'}
if($SelfTest){try{SelfTest;exit 0}catch{Write-Host 'SELF-TEST: FAIL';Write-Host $_.Exception.Message;exit 1}}
try{$Stage3V6RunRoot=(Resolve-Path -LiteralPath $Stage3V6RunRoot).ProviderPath;if(-not(Test-Path -LiteralPath $OutputRoot -PathType Container)){New-Item -ItemType Directory -Path $OutputRoot -Force|Out-Null};$OutputRoot=(Resolve-Path -LiteralPath $OutputRoot).ProviderPath;$summaryPath=Join-Path $Stage3V6RunRoot 'stage3-match-summary.json';$samplePath=Join-Path $Stage3V6RunRoot 'stage3-match-samples.csv';foreach($p in @($summaryPath,$samplePath)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "V6 artifact missing: $p"}};$summary=Get-Content -LiteralPath $summaryPath -Raw|ConvertFrom-Json;if([string]$summary.run_status-ne'PASS'-or[string]$summary.matching_contract-ne'CANDIDATE_V6'){throw'Input is not PASS CANDIDATE_V6.'};if((Get-Sha $samplePath)-ne([string]$summary.output.samples_sha256).ToLowerInvariant()){throw'V6 sample hash mismatch.'};$rows=@(Import-Csv -LiteralPath $samplePath);$logic=Assert-Logic $rows;if($logic.status-ne'PASS'){throw "V6 sample logic failed: $(@($logic.errors|Select-Object -First 5)-join'; ')"};$selected=@(Select-Rows $rows $PerStratum $MaxReviewRows);if($selected.Count-lt20){throw "V6 review unexpectedly small: $($selected.Count)"};$runId=(Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,8);$runDir=Join-Path $OutputRoot $runId;New-Item -ItemType Directory -Path $runDir -Force|Out-Null;$review=Join-Path $runDir 'stage3-v6-bounded-sample-review.csv';$out=New-Object System.Collections.ArrayList;$i=0;foreach($x in $selected){$i++;$r=$x.row;$o=[ordered]@{review_row_id=('S3V6R-{0:000}'-f$i);stratum=$x.stratum;stable_hash=$x.hash};foreach($name in @($r.PSObject.Properties.Name)){$o[$name]=[string]$r.$name};$o['review_decision']='';$o['review_note']='';[void]$out.Add([pscustomobject]$o)};@($out.ToArray())|Export-Csv -LiteralPath $review -NoTypeInformation -Encoding UTF8;$sum=[ordered]@{status='PASS';source_v6_summary_sha256=(Get-Sha $summaryPath);source_v6_sample_sha256=(Get-Sha $samplePath);source_rows=$rows.Count;automatic_logic_validation='PASS';review_rows=$out.Count;selection_rule='SHA-256 deterministic stratification plus mandatory IP Exchange, OM rally, OP_RETURN, IP infrastructure, Arweave (AR), Story (IP) cases';direct_semantic_review='UNVERIFIED';output_review_csv=$review;output_review_sha256=(Get-Sha $review);gate_CFA_S3F_023='UNVERIFIED';gate_CFA_S3F_024='BLOCKED';gate_CFA_S3_005='UNVERIFIED';gate_CFA_S3_006='BLOCKED'};Write-Utf8NoBom (Join-Path $runDir 'stage3-v6-bounded-sample-review-summary.json') (($sum|ConvertTo-Json -Depth 8)+[Environment]::NewLine);Write-Host '';Write-Host 'CFA STAGE 3 V6 BOUNDED SAMPLE PREPARATION: PASS';Write-Host("Source sample rows: {0}"-f$rows.Count);Write-Host("Review rows: {0}"-f$out.Count);Write-Host 'Automatic V6 rule consistency: PASS';Write-Host 'Direct semantic review: UNVERIFIED';Write-Host("Review CSV: {0}"-f$review);Write-Host("Evidence directory: {0}"-f$runDir);exit 0}catch{Write-Host '';Write-Host 'CFA STAGE 3 V6 BOUNDED SAMPLE PREPARATION: FAIL';Write-Host $_.Exception.Message;if($_.ScriptStackTrace){Write-Host $_.ScriptStackTrace};exit 1}
